using System.IO.Enumeration;
using Nadfny.Core;

namespace Nadfny.Features.Artifacts;

public sealed record GuardVerdict(string Path, bool Deletable, string Reason);

/// <summary>
/// Last line of defense before build output is deleted: proves a folder holds only generated files.
/// 1) In a git repo, any file inside that git tracks keeps the folder.
/// 2) Always: the contents are inspected, and any hand-written code file keeps the folder.
///    A code file counts as generated only by a known generated name, or by the marker that code
///    generators write in the header ("&lt;auto-generated&gt;", "DO NOT EDIT"...). Unsure means keep.
/// </summary>
public static class ArtifactGuard
{
    // Languages people write by hand, plus project/solution files. Build config (.props/.targets) and
    // platform stubs are not in the list: obj/ is full of generated ones.
    private static readonly HashSet<string> SourceExtensions = new(StringComparer.OrdinalIgnoreCase)
    {
        ".cs", ".vb", ".fs", ".razor", ".cshtml", ".csproj", ".vbproj", ".fsproj", ".sln", ".slnx",
        ".ts", ".tsx", ".jsx", ".vue", ".svelte", ".py", ".rs", ".go",
        ".js", ".mjs", ".cjs", ".gd", ".gdshader", ".dart", ".ex", ".exs", ".erl", ".hrl",
        ".swift", ".m", ".mm", ".h", ".hpp", ".c", ".cc", ".cpp", ".cxx", ".java", ".kt", ".kts",
    };

    private static readonly string[] GeneratedSuffixes =
    [
        ".g.cs", ".g.i.cs", ".AssemblyInfo.cs", ".AssemblyAttributes.cs", ".GlobalUsings.g.cs", ".razor.g.cs", ".cshtml.g.cs",
        ".designer.cs", ".d.ts",
    ];

    private static readonly string[] GeneratedMarkers =
    [
        "<auto-generated", "auto-generated", "autogenerated", "this code was generated", "do not edit", "do not modify", "@generated",
    ];

    private const int HeaderBytes = 2048;

    // Package/environment folders are regenerated wholesale and legitimately contain .ts/.py/.props files.
    private static readonly HashSet<string> PackageKinds = new(StringComparer.OrdinalIgnoreCase)
    {
        "node_modules", ".venv", "venv", ".next", ".vs",
    };

    public static async Task<IReadOnlyList<GuardVerdict>> EvaluateAsync(IReadOnlyList<string> folders, CancellationToken ct)
    {
        var verdicts = new List<GuardVerdict>();
        foreach (var group in folders.GroupBy(FindRepoRoot, StringComparer.OrdinalIgnoreCase))
        {
            var repo = group.Key;
            var list = group.ToList();
            if (repo is null)
            {
                verdicts.AddRange(list.Select(InspectContents));
                continue;
            }

            var tracked = await TrackedAsync(repo, list, ct);
            foreach (var f in list)
            {
                // Both checks always run: being git-ignored does not excuse a hand-written .cs file inside.
                verdicts.Add(tracked.Contains(f) ? new(f, false, "Kept: it contains files tracked by git.") : InspectContents(f));
            }
        }
        return verdicts;
    }

    public static GuardVerdict InspectContents(string folder)
    {
        if (PackageKinds.Contains(Path.GetFileName(folder))) return new(folder, true, "Package folder");
        var source = FindHandWrittenSource(folder);
        return source is null
            ? new(folder, true, "Only generated files")
            : new(folder, false, $"Kept: it contains source code ({Path.GetRelativePath(folder, source)}).");
    }

    internal static bool HasGeneratedName(string fileName) =>
        GeneratedSuffixes.Any(s => fileName.EndsWith(s, StringComparison.OrdinalIgnoreCase));

    /// <summary>True when the file's first 2 KB carry a code-generator marker. Unreadable means "not proven generated".</summary>
    internal static bool HasGeneratedHeader(string path)
    {
        try
        {
            using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
            var buffer = new byte[HeaderBytes];
            var read = stream.Read(buffer, 0, buffer.Length);
            var head = System.Text.Encoding.UTF8.GetString(buffer, 0, read);
            return GeneratedMarkers.Any(m => head.Contains(m, StringComparison.OrdinalIgnoreCase));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return false;
        }
    }

    private static string? FindHandWrittenSource(string folder)
    {
        var dotNetObj = Path.GetFileName(folder).Equals("obj", StringComparison.OrdinalIgnoreCase)
            && Path.GetDirectoryName(folder) is { } parent
            && ArtifactRules.Match("obj", new HashSet<string>(DirectorySizer.Shallow(parent)
                .Select(e => Path.GetFileName(e.Path)), StringComparer.OrdinalIgnoreCase))?.Tool == ".NET build";
        var options = new EnumerationOptions { RecurseSubdirectories = true, IgnoreInaccessible = true, AttributesToSkip = FileAttributes.ReparsePoint };
        var candidates = new FileSystemEnumerable<string>(folder, (ref FileSystemEntry e) => e.ToFullPath(), options)
        {
            ShouldIncludePredicate = (ref FileSystemEntry e) => !e.IsDirectory
                && SourceExtensions.Contains(Path.GetExtension(e.FileName).ToString())
                && !HasGeneratedName(e.FileName.ToString()),
        };
        // .NET's Android SDK writes platform stubs without headers under obj/.../android/src.
        bool AndroidStub(string file) => dotNetObj && Path.GetExtension(file).Equals(".java", StringComparison.OrdinalIgnoreCase)
            && ("/" + Path.GetRelativePath(folder, file).Replace('\\', '/')).Contains("/android/src/", StringComparison.OrdinalIgnoreCase);
        try { return candidates.FirstOrDefault(f => !AndroidStub(f) && !HasGeneratedHeader(f)); }
        catch (DirectoryNotFoundException) { return null; }
    }

    private static string? FindRepoRoot(string path)
    {
        for (var dir = new DirectoryInfo(path).Parent; dir is not null; dir = dir.Parent)
        {
            var git = Path.Combine(dir.FullName, ".git");
            if (Directory.Exists(git) || File.Exists(git)) return dir.FullName; // File.Exists: linked worktree
        }
        return null;
    }

    /// <summary>Folders (from the list) that contain at least one file git tracks.</summary>
    private static async Task<HashSet<string>> TrackedAsync(string repo, List<string> folders, CancellationToken ct)
    {
        var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var chunk in folders.Chunk(40)) // stay well under the command-line length limit
        {
            var rel = chunk.Select(f => Path.GetRelativePath(repo, f).Replace('\\', '/')).ToList();
            // Read-only listing. safe.directory lets us read repos copied from another Windows account (backups);
            // fsmonitor off means git runs no helper program from that repo's config while doing it.
            var res = await ProcessRunner.RunAsync("git", ["-c", $"safe.directory={repo.Replace('\\', '/')}", "-c", "core.fsmonitor=false", "-c", "core.quotepath=off", "-C", repo, "ls-files", "--", .. rel.Select(r => ":(literal)" + r)], repo, TimeSpan.FromSeconds(60), ct);
            if (!res.Ok)
            {
                // Could not prove anything: treat every folder in the chunk as tracked (kept).
                foreach (var f in chunk) result.Add(f);
                continue;
            }
            var files = res.StdOut.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            for (var i = 0; i < chunk.Length; i++)
            {
                var prefix = rel[i].TrimEnd('/') + "/";
                if (files.Any(f => f.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))) result.Add(chunk[i]);
            }
        }
        return result;
    }
}
